# R0_BLOCK=128 (smallest power-of-2 >= r0_numel=96): ~512 bytes SMEM/block
@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': x, 'R0_BLOCK': 128}, num_warps=w, num_stages=1)
        for x in [1, 2, 4, 8, 16, 32, 64, 128]
        for w in [2, 4, 8]
    ],
    key=['xnumel', 'r0_numel'],
)
@triton.jit
def kernel(..., XBLOCK: tl.constexpr, R0_BLOCK: tl.constexpr):
    r0_base = tl.arange(0, R0_BLOCK)[None, :]  # R0_BLOCK=128
    for r0_offset in tl.range(0, r0_numel, R0_BLOCK, num_stages=1):
        r0_index = r0_offset + r0_base
        r0_mask = r0_index < r0_numel
        # Vectorization hints on stride-1 r0 dimension (bias/scale/shift only)
        r0_2 = tl.max_contiguous(tl.multiple_of(r0_index, [1, 128]), [1, 128])
        tmp0 = tl.load(in_ptr0 + (x0 + stride*r0_index + ...), mask=r0_mask & xmask)  # strided: use r0_index
        tmp1 = tl.load(in_ptr1 + r0_2, mask=r0_mask & xmask)  # 128-bit vectorized
